CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'operacional',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS clientes (id SERIAL PRIMARY KEY,nome TEXT NOT NULL,cpf_cnpj TEXT UNIQUE,email TEXT,telefone TEXT,status TEXT NOT NULL DEFAULT 'ativo',created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documentos (id SERIAL PRIMARY KEY,cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,tipo TEXT NOT NULL,numero TEXT,validade DATE,status TEXT DEFAULT 'pendente',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS compras (id SERIAL PRIMARY KEY,cliente_id INTEGER NOT NULL REFERENCES clientes(id) ON DELETE CASCADE,data_compra DATE NOT NULL,valor NUMERIC(12,2) NOT NULL DEFAULT 0,descricao TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id SERIAL PRIMARY KEY,user_id INTEGER REFERENCES users(id),acao TEXT NOT NULL,entidade TEXT,entidade_id INTEGER,detalhes JSONB,created_at TIMESTAMPTZ DEFAULT now());